@info "  Notch sill z   : $(round(NOTCH_SILL_Z, digits=3)) m  (= slope at emb position)"
@info "  Notch width    : $(NOTCH_W_M) m  (sub-cell at res $MESH_RES, cell ≈ 22 m)"
@info "  Injection z    : $(round(INJ_Z, digits=3)) m"
@info "  Head to sill   : $(round(NOTCH_SILL_Z - INJ_Z, digits=3)) m"
@info "  Head to crest  : $(round(EMB_CREST_Z  - INJ_Z, digits=3)) m"

