# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

"""
    partition_cells(mesh) → (upstream_indices, downstream_indices)

Split cells into upstream (west of embankment body) and downstream (east).
Uses the partition_lon from the DEM params, which is one pixel east of the
embankment's east face — so embankment cells themselves are classified downstream
(conservative: they should have zero volume in normal operation).
"""
function partition_cells(mesh)
    up, dn = Int[], Int[]
    for (i, cell) in enumerate(mesh.cells)
        cell.center_lon < PART_LON ? push!(up, i) : push!(dn, i)
    end
    return up, dn
end

"""
    max_upstream_wse(state, solver, up_idx) → Float64

Return the maximum water surface elevation across all upstream cells.
This is the head at the embankment face.
"""
function max_upstream_wse(state, solver::Symbol, up_idx)
    wse_max = -Inf
    for i in up_idx
        wse = if solver == :sgs
            state.volume[i] > 0 ?
                A5Grid.wse_from_volume(state.sgs_tables[i], state.volume[i]) :
                state.sgs_tables[i].z_min
        else
            state.elevation[i] + state.volume[i] / max(state.cell_area[i], 1.0)
        end
        wse > wse_max && (wse_max = wse)
    end
    return wse_max
end

"""
    run_steps!(state, solver, n_steps, dt, inj_idx, inj_rate_m3s,
               up_idx, dn_idx; closed=true)

Advance the model n_steps steps of dt seconds, injecting inj_rate_m3s
into cell inj_idx before each step.

Returns (domain_vol, up_vol, dn_vol).

`closed=true` enforces closed boundaries (no ghost-edge outflow) by setting
all ghost BCs to Closed before the loop — the state passed in should already
have closed boundaries set via initialise_flow_model, but this is a safety guard.
"""
function run_steps!(state, solver::Symbol, n_steps::Int, dt::Float64,
                    inj_idx::Int, inj_rate_m3s::Float64,
                    up_idx, dn_idx)
    step_fn! = solver == :sgs ? step_sgs! : step_standard!

    # Standard solver requires water_depth pre-sync before first step
    if solver == :standard
        for i in eachindex(state.cell_ids)
            state.cell_area[i] >= 1.0 &&
                (state.water_depth[i] = state.volume[i] / state.cell_area[i])
        end
    end

    for _ in 1:n_steps
        state.volume[inj_idx] += inj_rate_m3s * dt
        step_fn!(state, dt)
    end

    dom = sum(state.volume)
    up  = sum(state.volume[i] for i in up_idx;  init=0.0)
    dn  = sum(state.volume[i] for i in dn_idx;  init=0.0)
    return dom, up, dn
end

"""
    make_output(path, interval_s) → SimOutput

Construct a SimOutput for HDF5 writing, creating the directory if needed.
"""
function make_output(path::String, interval_s::Float64)
    mkpath(dirname(path))
    SimOutput(path, interval_s, -Inf, 0, true)
end

# ---------------------------------------------------------------------------
# T0 — Mesh sanity
# ---------------------------------------------------------------------------
@testset "T0 — Mesh sanity: cells on both sides of embankment" begin
    for (label, mesh_file) in (("SGS", MESH_SGS), ("Std", MESH_STD))
        mesh  = A5Grid.load_mesh_geoparquet(mesh_file)
        up, dn = partition_cells(mesh)
        @test length(up) >= 5
        @test length(dn) >= 5
        @test length(up) + length(dn) <= length(mesh.cells) + 1
        @info "T0 [$label]: upstream=$(length(up))  downstream=$(length(dn))  " *
              "total=$(length(mesh.cells))"
    end
end

# ---------------------------------------------------------------------------
# T1 — Standard flow: no downstream water before crest exceeded
# ---------------------------------------------------------------------------
# With a closed domain and injection below the embankment crest, the standard
# solver cannot see the notch (it uses max(elev_i, elev_j) as sill).  Water
# should pond entirely upstream until WSE reaches emb_crest_z.
@testset "T1 — Standard: no downstream flow before embankment crest" begin
    mesh  = A5Grid.load_mesh_geoparquet(MESH_STD)
    state = initialise_flow_model(mesh, StandardFlow())
    # Enforce closed boundaries (default after this PR, but explicit for clarity)
    for i in eachindex(state.ghost_cell_bc)
        state.ghost_cell_bc[i] = Closed
    end
    up_idx, dn_idx = partition_cells(mesh)
    inj_idx, _, _  = _find_nearest_cell(mesh, INJ_LON, INJ_LAT)

    # Inject enough to fill upstream basin to ~75% of head needed to overtop.
    # The head needed is EMB_CREST_Z - INJ_Z.  We stop well short of that.
    # Injection rate: 50 mm/hr on one cell; dt=10s matches default dt_max.
    rate_m3s = (50.0 / 3_600_000.0) * state.cell_area[inj_idx]
    dt       = 10.0
    n_steps  = 600   # 600 × 10s = 6000s = 100 min

    _, _, dn_vol = run_steps!(state, :standard, n_steps, dt, inj_idx,
                               rate_m3s, up_idx, dn_idx)
    wse = max_upstream_wse(state, :standard, up_idx)

    @info "T1: max upstream WSE=$(round(wse,digits=3)) m  " *
          "emb_crest=$(round(EMB_CREST_Z,digits=3)) m  " *
          "downstream=$(round(dn_vol,digits=3)) m³"

    if wse < EMB_CREST_Z
        @test dn_vol < 1.0
        println("  T1 PASS: WSE $(round(wse,digits=3)) m < crest $(round(EMB_CREST_Z,digits=3)) m, " *
                "downstream=$(round(dn_vol,digits=3)) m³ ✓")
    else
        @warn "T1: WSE already at/above embankment crest — reduce injection rate or n_steps"
        @test_skip dn_vol < 1.0
    end
end

# ---------------------------------------------------------------------------
# T2 — SGS: downstream flow appears before embankment crest exceeded
# ---------------------------------------------------------------------------
# SGS detects the 3 m notch via pre-computed edge sills.  It should route
# water downstream once upstream WSE reaches NOTCH_SILL_Z — far below the
# embankment crest (difference = emb_height_m ≈ 2 m).
@testset "T2 — SGS: downstream flow at notch sill, well before crest" begin
    mesh  = A5Grid.load_mesh_geoparquet(MESH_SGS)
    state = initialise_flow_model(mesh, SGSFlow())
    for i in eachindex(state.ghost_cell_bc)
        state.ghost_cell_bc[i] = Closed
    end
    up_idx, dn_idx = partition_cells(mesh)
    inj_idx, _, _  = _find_nearest_cell(mesh, INJ_LON, INJ_LAT)

    # Phase 1: fill upstream to notch sill using high injection rate.
    rate_fill = (500.0 / 3_600_000.0) * state.cell_area[inj_idx]
    dt        = 10.0
    tol       = 0.05   # m — consider sill reached when within 5 cm

    wse = max_upstream_wse(state, :sgs, up_idx)
    fill_steps = 0
    while wse < NOTCH_SILL_Z - tol && fill_steps < 10_000
        run_steps!(state, :sgs, 100, dt, inj_idx, rate_fill, up_idx, dn_idx)
        fill_steps += 100
        wse = max_upstream_wse(state, :sgs, up_idx)
    end

    # Phase 2: continue for 1000 more steps so notch flow accumulates
    run_steps!(state, :sgs, 1000, dt, inj_idx, rate_fill, up_idx, dn_idx)
    total_steps = fill_steps + 1000

    dn_vol = sum(state.volume[i] for i in dn_idx; init=0.0)
    wse    = max_upstream_wse(state, :sgs, up_idx)

    @info "T2: WSE=$(round(wse,digits=4)) m after $(total_steps) steps  " *
          "downstream=$(round(dn_vol,digits=1)) m³  " *
          "(notch_sill=$(round(NOTCH_SILL_Z,digits=3)) m, " *
          "crest=$(round(EMB_CREST_Z,digits=3)) m)"

    # WSE should be at or above the notch sill but below the crest
    @test wse >= NOTCH_SILL_Z - tol
    @test dn_vol > 0.0
    # Key assertion: WSE is well below crest — SGS acted on sub-cell notch
    if wse < EMB_CREST_Z - 0.5
        println("  T2 PASS: SGS downstream=$(round(dn_vol,digits=1)) m³ " *
                "with WSE=$(round(wse,digits=3)) m << crest=$(round(EMB_CREST_Z,digits=3)) m ✓")
    else
        @warn "T2: WSE $(round(wse,digits=3)) m is close to or above crest — " *
              "notch may be too wide or mesh resolution too coarse"
    end
end

# ---------------------------------------------------------------------------
# T3 — SGS routes more downstream water than standard at same injection history
# ---------------------------------------------------------------------------
@testset "T3 — SGS routes more water through notch than standard at same injection" begin
    mesh_sgs = A5Grid.load_mesh_geoparquet(MESH_SGS)
    mesh_std = A5Grid.load_mesh_geoparquet(MESH_STD)
    state_sgs = initialise_flow_model(mesh_sgs, SGSFlow())
    state_std = initialise_flow_model(mesh_std, StandardFlow())

    for i in eachindex(state_sgs.ghost_cell_bc); state_sgs.ghost_cell_bc[i] = Closed; end
    for i in eachindex(state_std.ghost_cell_bc); state_std.ghost_cell_bc[i] = Closed; end

    up_sgs, dn_sgs = partition_cells(mesh_sgs)
    up_std, dn_std = partition_cells(mesh_std)
    inj_sgs, _, _  = _find_nearest_cell(mesh_sgs, INJ_LON, INJ_LAT)
    inj_std, _, _  = _find_nearest_cell(mesh_std, INJ_LON, INJ_LAT)

    rate_sgs  = (500.0 / 3_600_000.0) * state_sgs.cell_area[inj_sgs]
    rate_std  = (500.0 / 3_600_000.0) * state_std.cell_area[inj_std]
    dt        = 10.0
    tol       = 0.05

    # Phase 1: fill SGS to notch sill
    wse_sgs = max_upstream_wse(state_sgs, :sgs, up_sgs)
    steps = 0
    while wse_sgs < NOTCH_SILL_Z - tol && steps < 10_000
        run_steps!(state_sgs, :sgs, 100, dt, inj_sgs, rate_sgs, up_sgs, dn_sgs)
        steps   += 100
        wse_sgs  = max_upstream_wse(state_sgs, :sgs, up_sgs)
    end

    # Phase 2: 2000 more steps for notch flow to accumulate
    run_steps!(state_sgs, :sgs, 2000, dt, inj_sgs, rate_sgs, up_sgs, dn_sgs)
    steps += 2000

    # Advance standard for identical total steps and injection rate
    run_steps!(state_std, :standard, steps, dt, inj_std, rate_std, up_std, dn_std)

    dn_sgs_vol = sum(state_sgs.volume[i] for i in dn_sgs; init=0.0)
    dn_std_vol = sum(state_std.volume[i] for i in dn_std; init=0.0)
    wse_std    = max_upstream_wse(state_std, :standard, up_std)
    wse_sgs_f  = max_upstream_wse(state_sgs, :sgs, up_sgs)

    @info "T3 after $(steps) steps:"
    @info "  SGS: WSE=$(round(wse_sgs_f,digits=3)) m  downstream=$(round(dn_sgs_vol,digits=1)) m³"
    @info "  Std: WSE=$(round(wse_std,digits=3)) m  downstream=$(round(dn_std_vol,digits=1)) m³"

    @test dn_sgs_vol > dn_std_vol
    println("  T3 PASS: SGS=$(round(dn_sgs_vol,digits=1)) m³ > " *
            "Std=$(round(dn_std_vol,digits=1)) m³ downstream ✓")
    println("  T3: SGS routed $(round(dn_sgs_vol / max(dn_std_vol, 1.0), digits=1))× " *
            "more water than standard at same injection history")
end

# ---------------------------------------------------------------------------
# T4 — Mass balance: both solvers, closed domain
# ---------------------------------------------------------------------------
@testset "T4 — Mass balance: closed domain, both solvers" begin
    for (solver_sym, mesh_file) in ((:sgs, MESH_SGS), (:standard, MESH_STD))
        mesh  = A5Grid.load_mesh_geoparquet(mesh_file)
        state = solver_sym == :sgs ?
                initialise_flow_model(mesh, SGSFlow()) :
                initialise_flow_model(mesh, StandardFlow())
        for i in eachindex(state.ghost_cell_bc)
            state.ghost_cell_bc[i] = Closed
        end

        up_idx, dn_idx = partition_cells(mesh)
        inj_idx, _, _  = _find_nearest_cell(mesh, INJ_LON, INJ_LAT)
        rate_m3s = (100.0 / 3_600_000.0) * state.cell_area[inj_idx]
        dt, n_steps = 10.0, 600

        step_fn! = solver_sym == :sgs ? step_sgs! : step_standard!
        if solver_sym == :standard
            for i in eachindex(state.cell_ids)
                state.cell_area[i] >= 1.0 &&
                    (state.water_depth[i] = state.volume[i] / state.cell_area[i])
            end
        end

        total_inj = 0.0
        for _ in 1:n_steps
            added = rate_m3s * dt
            state.volume[inj_idx] += added
            total_inj += added
            step_fn!(state, dt)
        end

        dom_vol    = sum(state.volume)
        mb_err_pct = 100.0 * abs(dom_vol - total_inj) / total_inj

        @test mb_err_pct < 0.01
        @info "T4 ($solver_sym): injected=$(round(total_inj,digits=1)) m³  " *
              "domain=$(round(dom_vol,digits=3)) m³  " *
              "err=$(round(mb_err_pct, sigdigits=3))%"
        println("  T4 PASS ($solver_sym): mass balance $(round(mb_err_pct, sigdigits=3))% ✓")
    end
end

# ---------------------------------------------------------------------------
# T5 — Full simulation runs with HDF5 output
# ---------------------------------------------------------------------------
# This test runs both solvers for the full simulation duration and writes
# HDF5 output files.  It then verifies the files are valid.
# The simulations here use run_simulation! directly so they include the
# complete output pipeline (HDF5 frames, mass balance logging, timing).
#
# Simulation parameters:
#   Duration : 7200 s (2 hours) — enough for clear upstream/downstream contrast
#   dt_max   : 10 s  — matches LISFLOOD-FP default
#   Injection: 50 mm/hr into the upstream cell
#   BC       : Closed (no outflow) so mass balance is exact
@testset "T5 — Full simulation with HDF5 output" begin
    inj_rate_mm_hr = 50.0
    sim_duration   = 7200.0    # s
    dt_max         = 10.0      # s
    output_interval = 300.0    # s — 24 frames for a 2-hour run

    for (solver_sym, mesh_file, h5_path) in (
            (:sgs,      MESH_SGS, H5_SGS),
            (:standard, MESH_STD, H5_STD))

        @info "T5: running $(solver_sym) simulation ($(sim_duration/3600) h)..."
        t_start = time()

        mesh   = A5Grid.load_mesh_geoparquet(mesh_file)
        method = solver_sym == :sgs ? SGSFlow() : StandardFlow()
        state  = initialise_flow_model(mesh, method)

        # Closed boundaries
        for i in eachindex(state.ghost_cell_bc)
            state.ghost_cell_bc[i] = Closed
        end

        inj_idx, _, dist_m = _find_nearest_cell(mesh, INJ_LON, INJ_LAT)
        @info "  Injection cell: idx=$inj_idx  dist=$(round(dist_m,digits=0)) m from target"

        rate_m3s = (inj_rate_mm_hr / 3_600_000.0) * state.cell_area[inj_idx]
        sources  = AbstractSource[
            RainPoint(inj_idx, state.cell_ids[inj_idx],
                      rate_m3s, INJ_LON, INJ_LAT, inj_rate_mm_hr)
        ]

        sim_output = make_output(h5_path, output_interval)

        # Makie visualisation for the first solver if --vis flag given
        vis, vis_mode = nothing, :none
        if SHOW_VIS && solver_sym == :standard
            @info "  Opening Makie visualiser for standard flow run..."
            # MakieVisualiser is loaded as part of FloodModel.jl include above
            vis_mode = :makie
            vis = MakieVisualiser.start(mesh;
                      source_indices = [inj_idx],
                      adjacency      = state.adjacency,
                      title          = "Planar embankment — standard flow")
        end

        tl = TimingLog()
        run_simulation!(state, mesh, sim_duration, dt_max,
                        vis, vis_mode, sim_output;
                        method      = method,
                        all_sources = sources,
                        timing      = tl)

        elapsed = round(time() - t_start, digits=1)
        @info "  $(solver_sym) done in $(elapsed) s  " *
              "($(tl.n_steps) steps, $(sim_output.frame_count) frames)"

        # Close visualiser if open
        if vis !== nothing && vis_mode === :makie
            MakieVisualiser.stop(vis)
        end

        # Verify HDF5 output
        @test isfile(h5_path)

        if isfile(h5_path)
            HDF5.h5open(h5_path, "r") do f
                frames   = sort(keys(f["frames"]))
                n_frames = length(frames)
                @test n_frames >= 10

                last_key = frames[end]
                depth    = read(f["frames/$last_key/water_depth"])
                max_d    = maximum(depth; init=0.0)
                @test max_d > 0.1

                # Mass balance from HDF5 data
                last_vol = sum(read(f["frames/$last_key/volume"]))
                @info "  T5 [$solver_sym] HDF5: $n_frames frames, " *
                      "max_depth=$(round(max_d,digits=3)) m, " *
                      "final_vol=$(round(last_vol/1e3,digits=1)) km³... wait, " *
                      "$(round(last_vol,digits=0)) m³"
            end
            println("  T5 PASS ($solver_sym): HDF5 output valid ✓  → $h5_path")
        end
    end
end

